1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "title": "Review completion signal v1.0.0",
4	  "description": "Written once by the native reviewer session to <run>/review.completion.json. The controller accepts it only when it validates here, its bindings match the run (run_id, review node, launch_token from the reviewer prompt, bundle SHA-256 and candidate commit from review-bundle.json) and the reviewer session is idle or done. A verdict of blocked, or any P0/P1 finding that is not resolved, ends the run; no second reviewer is launched.",
5	  "type": "object",
6	  "additionalProperties": false,
7	  "required": ["version", "run_id", "node_id", "launch_token", "bundle_sha256", "candidate_commit", "verdict", "findings"],
8	  "properties": {
9	    "version": {"const": "1.0.0"},
10	    "run_id": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$"},
11	    "node_id": {"const": "review"},
12	    "launch_token": {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},
13	    "bundle_sha256": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
14	    "candidate_commit": {"type": "string", "pattern": "^[a-f0-9]{40}$"},
15	    "verdict": {"enum": ["approved", "blocked"]},
16	    "findings": {
17	      "type": "array",
18	      "items": {
19	        "type": "object",
20	        "additionalProperties": false,
21	        "required": ["severity", "message", "disposition", "worker", "requirement"],
22	        "properties": {
23	          "severity": {"enum": ["P0", "P1", "P2"]},
24	          "message": {"type": "string", "minLength": 1},
25	          "disposition": {"enum": ["open", "resolved", "accepted"]},
26	          "worker": {
27	            "description": "Which worker's assignment the finding concerns: ui, adapter, both, or none for cross-cutting/policy findings.",
28	            "enum": ["ui", "adapter", "both", "none"]
29	          },
30	          "requirement": {
31	            "description": "A verbatim quote from that worker's task text that the finding relates to, or null when no single requirement applies. Consumers link a finding to its task only when the quote is found verbatim; nothing is inferred.",
32	            "type": ["string", "null"],
33	            "minLength": 1
34	          }
35	        }
36	      }
37	    }
38	  }
39	}
